let suggestedFilms=[];function pickSuggestionSeeds(){const favs=films.filter(f=>f.fav&&f.tmdbId);if(favs.length>0)return favs.slice(0,5);return films.filter(f=>f.tmdbId&&getDisplayNote(f)!==null&&getDisplayNote(f)>=4).sort((a,b)=>getDisplayNote(b)-getDisplayNote(a)).slice(0,5)}function suggestionItemHtml(r){const year=r.release_date?r.release_date.slice(0,4):null;const poster=r.poster_path?TMDB_IMG_BASE+r.poster_path:null;const label=`${r.title}${year?` (${year})`:``}`;return`
    <div class="wls-item">
      <button class="wls-poster" type="button" data-action="open-film" data-id="${r.id}" title="${escapeHtml(label)}" aria-label="Voir la fiche de ${escapeHtml(label)}">
        ${poster?`<img src="${escapeHtml(poster)}" alt="" loading="lazy" decoding="async">`:`<span class="film-poster-placeholder">${FILM_PLACEHOLDER_SVG}</span>`}
      </button>
      <button class="wls-add" data-action="add-watchlist" data-id="${r.id}" type="button" aria-label="Ajouter ${escapeHtml(label)} à À voir">+ À voir</button>
    </div>
  `}function renderSuggestionsList(){const list=document.getElementById(`suggestionsList`);list.innerHTML=suggestedFilms.map(suggestionItemHtml).join(``);list.querySelectorAll(`[data-action="add-watchlist"]`).forEach(btn=>{btn.addEventListener(`click`,withSubmitGuard(btn,()=>addSuggestionToWatchlist(Number(btn.dataset.id))))});const navList=suggestedFilms.map(r=>({tmdbId:r.id,title:r.title}));list.querySelectorAll(`[data-action="open-film"]`).forEach(btn=>{btn.addEventListener(`click`,()=>goToFilmDetail(Number(btn.dataset.id),navList))})}async function loadSuggestions(){const section=document.getElementById(`suggestionsSection`);const seeds=pickSuggestionSeeds();if(seeds.length===0){section.style.display=`none`;return}if(watchlist.length===0)await loadWatchlist();const known=new Set([...films.filter(f=>f.tmdbId).map(f=>f.tmdbId),...watchlist.filter(w=>w.tmdbId).map(w=>w.tmdbId)]);const perSeedResults=await Promise.all(seeds.map(async seed=>{try{const url=`https://api.themoviedb.org/3/movie/${seed.tmdbId}/recommendations?language=fr-FR`;const res=await fetch(url,{headers:{Authorization:`Bearer ${TMDB_API_KEY}`,Accept:`application/json`}});if(!res.ok)return[];const data=await res.json();return data.results||[]}catch(e){console.error(e);return[]}}));const scoreById={};const infoById={};perSeedResults.flat().forEach(r=>{if(known.has(r.id))return;scoreById[r.id]=(scoreById[r.id]||0)+1;if(!infoById[r.id])infoById[r.id]=r});suggestedFilms=Object.keys(scoreById).map(id=>({id:Number(id),score:scoreById[id]})).sort((a,b)=>b.score-a.score||(infoById[b.id].vote_average||0)-(infoById[a.id].vote_average||0)).slice(0,10).map(x=>infoById[x.id]);if(suggestedFilms.length===0){section.style.display=`none`;return}section.style.display=``;renderSuggestionsList()}async function addSuggestionToWatchlist(tmdbId){const r=suggestedFilms.find(x=>x.id===tmdbId);if(!r)return;const item=await addTmdbMovieToWatchlist(r);if(!item)return;suggestedFilms=suggestedFilms.filter(x=>x.id!==tmdbId);if(suggestedFilms.length===0)document.getElementById(`suggestionsSection`).style.display=`none`;else renderSuggestionsList();showToast(`Ajouté à À voir`)}